func NormalizeErrorReason(values ...string) string {
	for _, value := range values {
		candidate := strings.TrimSpace(strings.SplitN(value, ":", 2)[0])
		if _, ok := ErrorReasonPolicies[candidate]; ok { return candidate }
		if reason, ok := ErrorReasonAliases[candidate]; ok { return reason }
		if reason, ok := ErrorReasonAliases[strings.ToLower(candidate)]; ok { return reason }
		for alias, reason := range ErrorReasonAliases { if strings.EqualFold(alias, candidate) { return reason } }
	}
	return "hook_handler_failed"
}
